INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','modal-deduction','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"modal-deduction","title":"Deductions and degrees of certainty","level":"B2","order":40,"summary":"Express conclusions and possibilities without confusing certainty with obligation.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A strong positive conclusion","A strong negative conclusion","An uncertain possibility","Match the verb form to the time"],"rules":[{"title":"A strong positive conclusion","explanation":"Must can express a strong deduction based on evidence. This differs from must as an obligation. Must be working means the speaker concludes that the activity is happening; it does not necessarily order anyone to work.","pattern":"The lights are on; someone **must be working**.","commonMistakes":["A deduction is the speaker’s judgement, not an absolute guarantee."],"examples":["You draw a strong positive conclusion from clear evidence: “They **must** be preparing the visitor guide.”","You draw a strong positive conclusion from clear evidence: “They **must** be restoring the old portrait.”"],"skill":"form"},{"title":"A strong negative conclusion","explanation":"Can’t and cannot can express that something is impossible according to the available evidence. Mustn’t normally expresses prohibition rather than the ordinary negative counterpart of deductive must.","pattern":"That **can’t be** the right address.","commonMistakes":["Do not substitute mustn’t when you mean that something is impossible."],"examples":["The evidence rules this out as impossible: “They **cannot** be preparing the visitor guide.”","The evidence rules this out as impossible: “They **cannot** be restoring the old portrait.”"],"skill":"meaning"},{"title":"An uncertain possibility","explanation":"May, might and could often express an uncertain possibility. Their relative strength depends on context, intonation and variety, so these exercises do not assign fixed percentage probabilities. A negative may not or might not means possibly not.","pattern":"She **might be** at home.","commonMistakes":["Could not often suggests impossibility; it is not always interchangeable with might not."],"examples":["The evidence is inconclusive; this is only possible: “They **might** be preparing the visitor guide.”","The evidence is inconclusive; this is only possible: “They **might** be restoring the old portrait.”"],"skill":"contrast"},{"title":"Match the verb form to the time","explanation":"For a present activity, use modal + be + -ing. For a state, use modal + base verb. Future probability can also use be likely to or probably. Keep probably before a negative modal in the common phrase probably won’t.","pattern":"They **must be waiting**. / They **are likely to arrive** soon.","commonMistakes":["A present deduction about an activity needs be before -ing; must waiting is incomplete."],"examples":["Build a deduction about an action happening now: “She must **be preparing** the visitor guide.”","Build a deduction about an action happening now: “She must **be restoring** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"fb95e61f-bdc9-5af8-ab2d-1b1feb0b78fe","topicSlug":"modal-deduction","level":"B2","prompt":"You draw a strong positive conclusion from clear evidence: “They ____ be preparing the visitor guide.”","choices":[{"id":"A","text":"might"},{"id":"B","text":"must"},{"id":"C","text":"must not"},{"id":"D","text":"cannot"}],"answerId":"B","hint":"Identify the intended strength: **strong positive deduction**.","explanation":"Deductive **must** expresses the strong positive conclusion requested.","keywords":["strong-positive-deduction"],"skill":"strong-positive-deduction","contextKey":"modal-deduction-1","fingerprint":"a623ce82a61324b1f2046b12233ddccbc7ac7aff95b0afa152100720a3c2de1a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the intended strength: **strong positive deduction**.","Deductive **must** expresses the strong positive conclusion requested.","Choose **must**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Might expresses uncertainty rather than the requested strong conclusion.","B":"Deductive **must** expresses the strong positive conclusion requested.","C":"Must not normally conveys prohibition, not a positive deduction.","D":"Cannot expresses a negative conclusion, the opposite of the prompt."}}},{"id":"57f65b14-09d6-54f2-ae50-53516373755f","topicSlug":"modal-deduction","level":"B2","prompt":"The evidence rules this out as impossible: “They ____ be preparing the visitor guide.”","choices":[{"id":"A","text":"must"},{"id":"B","text":"may"},{"id":"C","text":"must not"},{"id":"D","text":"cannot"}],"answerId":"D","hint":"Choose the modal for an **impossible explanation**, not a prohibition.","explanation":"**Cannot** expresses impossibility according to the stated evidence.","keywords":["impossibility"],"skill":"impossibility","contextKey":"modal-deduction-1","fingerprint":"c1eb8957caca127906cb9c1aa0c0142cb1b85d7904e8aae72a2e5a909891acf4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Choose the modal for an **impossible explanation**, not a prohibition.","**Cannot** expresses impossibility according to the stated evidence.","Choose **cannot**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Must would give a strong positive conclusion.","B":"May would leave the event possible.","C":"Must not normally prohibits an action rather than ruling it out as impossible.","D":"**Cannot** expresses impossibility according to the stated evidence."}}},{"id":"224ea454-d807-5b0e-a12e-13e4ebeae90d","topicSlug":"modal-deduction","level":"B2","prompt":"The evidence is inconclusive; this is only possible: “They ____ be preparing the visitor guide.”","choices":[{"id":"A","text":"might"},{"id":"B","text":"must"},{"id":"C","text":"cannot"},{"id":"D","text":"have to"}],"answerId":"A","hint":"The prompt says **possible but uncertain**.","explanation":"**Might** leaves the action possible without claiming certainty.","keywords":["uncertain-possibility"],"skill":"uncertain-possibility","contextKey":"modal-deduction-1","fingerprint":"d6a6b551b13e09faf1400313ef4e5b81b85df2287d6665e831c1b1e275d826a3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The prompt says **possible but uncertain**.","**Might** leaves the action possible without claiming certainty.","Choose **might**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Might** leaves the action possible without claiming certainty.","B":"Must would express a stronger positive conclusion than the prompt supports.","C":"Cannot rules the action out.","D":"Have to ordinarily introduces a requirement here, not the requested uncertain possibility."}}},{"id":"f5186d67-3661-5c27-a52d-5bed3aff0cf0","topicSlug":"modal-deduction","level":"B2","prompt":"Build a deduction about an action happening now: “She must ____ the visitor guide.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"is preparing"},{"id":"C","text":"been preparing"},{"id":"D","text":"be preparing"}],"answerId":"D","hint":"A present ongoing deduction has the form **modal + be + -ing**.","explanation":"After must, use **be + preparing** for an ongoing action.","keywords":["deduction-continuous-form"],"skill":"deduction-continuous-form","contextKey":"modal-deduction-1","fingerprint":"4d4802a05faf9648736b5dc8b78efb46152bd6f6f7474ebffb5f93f5b999aa6b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A present ongoing deduction has the form **modal + be + -ing**.","After must, use **be + preparing** for an ongoing action.","Choose **be preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The auxiliary be is missing.","B":"Must takes base be, not finite is.","C":"Been requires a perfect auxiliary have before it.","D":"After must, use **be + preparing** for an ongoing action."}}},{"id":"bbca5ff7-b7c0-5ed4-a36b-3861ea4664f3","topicSlug":"modal-deduction","level":"B2","prompt":"You draw a strong positive conclusion from clear evidence: “They ____ be restoring the old portrait.”","choices":[{"id":"A","text":"must"},{"id":"B","text":"must not"},{"id":"C","text":"cannot"},{"id":"D","text":"might"}],"answerId":"A","hint":"Identify the intended strength: **strong positive deduction**.","explanation":"Deductive **must** expresses the strong positive conclusion requested.","keywords":["strong-positive-deduction"],"skill":"strong-positive-deduction","contextKey":"modal-deduction-2","fingerprint":"5529eab2c0c87a084385f1661030e95fff24a90388414b31772dbeae32cad982","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-deduction"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps"